/* _RA_CORE is supplied by e2 studio's selected processor. */ #define BSP_PRV_CORE_ID_CM85 (1) #define BSP_PRV_CORE_ID_CM33 (2) #define BSP_PRV_CORE_ID_(core) BSP_PRV_CORE_ID_ ## core #define BSP_PRV_CORE_ID(core) BSP_PRV_CORE_ID_(core) #if !defined(_RA_CORE) #error "e2 studio must select _RA_CORE=CM85 or CM33" #elif BSP_PRV_CORE_ID(_RA_CORE) == 1 #define BSP_CFG_CPU_CORE (0) #elif BSP_PRV_CORE_ID(_RA_CORE) == 2 #define BSP_CFG_CPU_CORE (1) #else #error "Unsupported RA8P1 processor selected by _RA_CORE" #endif #include "bsp_mcu_device_pn_cfg.h" #include "bsp_mcu_device_cfg.h" #include "../../../ra/fsp/src/bsp/mcu/ra8p1/bsp_override.h" #include "../../../ra/fsp/src/bsp/mcu/ra8p1/bsp_mcu_info.h" #include "bsp_clock_cfg.h" #define BSP_MCU_GROUP_RA8P1 (1) #if (BSP_CFG_CPU_CORE == 0) && (${config.bsp.fsp.secondary_core_start} != 0U) #define BSP_CFG_SECONDARY_CORE_START_ADDRESS (${config.bsp.fsp.secondary_core_start}) #endif /* A disabled GPTCLK leaves the hardware on the reset oscillator unless GPT selects PCLKD. */ #define BSP_CFG_GPT_COUNT_CLOCK_SOURCE (BSP_CFG_GPTCLK_SOURCE == BSP_CLOCKS_CLOCK_DISABLED) #define BSP_CFG_MRPCLK_DIV BSP_CFG_FCLK_DIV #define BSP_CFG_CPUCLK0_DIV BSP_CFG_CPUCLK_DIV #define BSP_CFG_CPUCLK1_DIV BSP_CFG_EXTRACLK1_DIV #define BSP_CFG_NPUCLK_DIV BSP_CFG_EXTRACLK2_DIV #define BSP_CFG_MRICLK_DIV BSP_CFG_EXTRACLK3_DIV #define BSP_LOCO_HZ (32768) #define BSP_MOCO_HZ (8000000) #define BSP_SUB_CLOCK_HZ (0) #if BSP_CFG_HOCO_FREQUENCY == 0 #define BSP_HOCO_HZ (16000000) #elif BSP_CFG_HOCO_FREQUENCY == 1 #define BSP_HOCO_HZ (18000000) #elif BSP_CFG_HOCO_FREQUENCY == 2 #define BSP_HOCO_HZ (20000000) #elif BSP_CFG_HOCO_FREQUENCY == 4 #define BSP_HOCO_HZ (32000000) #elif BSP_CFG_HOCO_FREQUENCY == 7 #define BSP_HOCO_HZ (48000000) #else #error "Invalid HOCO frequency chosen (BSP_CFG_HOCO_FREQUENCY) in bsp_clock_cfg.h" #endif
#define BSP_CFG_FLL_ENABLE (${config.bsp.fsp.hoco_fll})
#define BSP_CFG_CLOCK_SETTLING_DELAY_ENABLE (${config.bsp.fsp.clock_settling_delay}) #define BSP_CFG_SLEEP_MODE_DELAY_ENABLE (${config.bsp.fsp.sleep_mode_delays}) #define BSP_CFG_MSTP_CHANGE_DELAY_ENABLE (${config.bsp.fsp.mstp_change_delays}) #define BSP_CFG_RTOS_IDLE_SLEEP (${config.bsp.fsp.rtos_idle_sleep}) #define BSP_CFG_CLOCK_SETTLING_DELAY_US (${config.bsp.fsp.settling_delay_us})
#if defined(BSP_PACKAGE_LQFP) && (BSP_PACKAGE_PINS == 100) #define BSP_MAX_CLOCK_CHANGE_THRESHOLD (180000000U) #elif defined(BSP_PACKAGE_LQFP) #define BSP_MAX_CLOCK_CHANGE_THRESHOLD (200000000U) #else #define BSP_MAX_CLOCK_CHANGE_THRESHOLD (240000000U) #endif
#define BSP_CORTEX_VECTOR_TABLE_ENTRIES (16U) #define BSP_VECTOR_TABLE_MAX_ENTRIES (112U) #define BSP_CFG_INLINE_IRQ_FUNCTIONS (${config.bsp.fsp.inline_irq_functions})
#if defined(_RA_TZ_SECURE) #define BSP_TZ_SECURE_BUILD (1) #define BSP_TZ_NONSECURE_BUILD (0) #elif defined(_RA_TZ_NONSECURE) #define BSP_TZ_SECURE_BUILD (0) #define BSP_TZ_NONSECURE_BUILD (1) #else #define BSP_TZ_SECURE_BUILD (0) #define BSP_TZ_NONSECURE_BUILD (0) #endif
/* TrustZone Settings */ #define BSP_TZ_CFG_INIT_SECURE_ONLY (BSP_CFG_CLOCKS_SECURE || (!BSP_CFG_CLOCKS_OVERRIDE)) #define BSP_TZ_CFG_SKIP_INIT (BSP_TZ_NONSECURE_BUILD && BSP_TZ_CFG_INIT_SECURE_ONLY) #define BSP_TZ_CFG_EXCEPTION_RESPONSE (${config.bsp.fsp.tz.exception_response})
/* CMSIS TrustZone Settings */ #define SCB_CSR_AIRCR_INIT (1) #define SCB_AIRCR_BFHFNMINS_VAL (${config.bsp.fsp.tz.cmsis.bfhfnmins}) #define SCB_AIRCR_SYSRESETREQS_VAL (${config.bsp.fsp.tz.cmsis.sysresetreqs}) #define SCB_AIRCR_PRIS_VAL (${config.bsp.fsp.tz.cmsis.s_priority_boost}) #define TZ_FPU_NS_USAGE (1) #ifndef SCB_NSACR_CP10_11_VAL #define SCB_NSACR_CP10_11_VAL (3U) #endif
#ifndef FPU_FPCCR_TS_VAL #define FPU_FPCCR_TS_VAL (1U) #endif #define FPU_FPCCR_CLRONRETS_VAL (1)
#ifndef FPU_FPCCR_CLRONRET_VAL #define FPU_FPCCR_CLRONRET_VAL (1) #endif
/* Type 1 Peripheral Security Attribution */
/* Peripheral Security Attribution Register (PSAR) Settings */ #ifndef BSP_TZ_CFG_PSARB #define BSP_TZ_CFG_PSARB (\ ((((${interface.peripheral.i3c} > 0)) ? 0U : 1U) << 4U) | \ ((((${interface.peripheral.iic2} > 0)) ? 0U : 1U) << 7U) | \ ((((${interface.peripheral.iic1} > 0)) ? 0U : 1U) << 8U) | \ ((((${interface.peripheral.iic0} > 0)) ? 0U : 1U) << 9U) | \ ((((${interface.peripheral.usbfs} > 0)) ? 0U : 1U) << 11U) | \ ((((${interface.peripheral.usbhs} > 0)) ? 0U : 1U) << 12U) | \ ((((${interface.peripheral.ospi_b0} > 0) || (${interface.peripheral.dotf0} > 0)) ? 0U : 1U) << 16U) | \ ((((${interface.peripheral.ospi_b1} > 0) || (${interface.peripheral.dotf1} > 0)) ? 0U : 1U) << 17U) | \ ((((${interface.peripheral.spi1} > 0)) ? 0U : 1U) << 18U) | \ ((((${interface.peripheral.spi0} > 0)) ? 0U : 1U) << 19U) | \ ((((${interface.peripheral.sci9} > 0)) ? 0U : 1U) << 22U) | \ ((((${interface.peripheral.sci8} > 0)) ? 0U : 1U) << 23U) | \ ((((${interface.peripheral.sci7} > 0)) ? 0U : 1U) << 24U) | \ ((((${interface.peripheral.sci6} > 0)) ? 0U : 1U) << 25U) | \ ((((${interface.peripheral.sci5} > 0)) ? 0U : 1U) << 26U) | \ ((((${interface.peripheral.sci4} > 0)) ? 0U : 1U) << 27U) | \ ((((${interface.peripheral.sci3} > 0)) ? 0U : 1U) << 28U) | \ ((((${interface.peripheral.sci2} > 0)) ? 0U : 1U) << 29U) | \ ((((${interface.peripheral.sci1} > 0)) ? 0U : 1U) << 30U) | \ ((((${interface.peripheral.sci0} > 0)) ? 0U : 1U) << 31U)) #endif #ifndef BSP_TZ_CFG_PSARC #define BSP_TZ_CFG_PSARC (\ ((((${interface.peripheral.cac} > 0)) ? 0U : 1U) << 0U) | \ ((((${interface.peripheral.crc} > 0)) ? 0U : 1U) << 1U) | \ ((((${interface.peripheral.ssie1} > 0)) ? 0U : 1U) << 7U) | \ ((((${interface.peripheral.ssie0} > 0)) ? 0U : 1U) << 8U) | \ ((((${interface.peripheral.sdhi1} > 0)) ? 0U : 1U) << 11U) | \ ((((${interface.peripheral.sdhi0} > 0)) ? 0U : 1U) << 12U) | \ ((((${interface.peripheral.doc} > 0)) ? 0U : 1U) << 13U) | \ ((((${interface.peripheral.glcdc} > 0) || (${interface.peripheral.mipi_dsi} > 0) || (${interface.peripheral.mipi_csi} > 0) || (${interface.peripheral.drw} > 0)) ? 0U : 1U) << 15U) | \ ((((${interface.peripheral.ceu} > 0)) ? 0U : 1U) << 16U) | \ ((((${interface.peripheral.pdm} > 0)) ? 0U : 1U) << 24U) | \ ((((${interface.peripheral.canfd1} > 0)) ? 0U : 1U) << 26U) | \ ((((${interface.peripheral.canfd0} > 0)) ? 0U : 1U) << 27U) | \ ((((${interface.peripheral.ethphyclk} > 0)) ? 0U : 1U) << 28U) | \ ((((${interface.peripheral.eswm} > 0)) ? 0U : 1U) << 30U) | \ ((((${interface.peripheral.rsip} > 0)) ? 0U : 1U) << 31U)) #endif #ifndef BSP_TZ_CFG_PSARD #define BSP_TZ_CFG_PSARD (\ ((((${interface.peripheral.agt1} > 0)) ? 0U : 1U) << 4U) | \ ((((${interface.peripheral.agt0} > 0)) ? 0U : 1U) << 5U) | \ ((((${interface.peripheral.pdg} > 0)) ? 0U : 1U) << 6U) | \ ((((${interface.peripheral.poeg3} > 0)) ? 0U : 1U) << 11U) | \ ((((${interface.peripheral.poeg2} > 0)) ? 0U : 1U) << 12U) | \ ((((${interface.peripheral.poeg1} > 0)) ? 0U : 1U) << 13U) | \ ((((${interface.peripheral.poeg0} > 0)) ? 0U : 1U) << 14U) | \ ((((${interface.peripheral.dac_b1} > 0)) ? 0U : 1U) << 19U) | \ ((((${interface.peripheral.dac_b0} > 0)) ? 0U : 1U) << 20U) | \ ((((${interface.peripheral.adc} > 0)) ? 0U : 1U) << 21U) | \ ((((${interface.peripheral.tsn} > 0)) ? 0U : 1U) << 22U) | \ ((((${interface.peripheral.acmphs3} > 0)) ? 0U : 1U) << 25U) | \ ((((${interface.peripheral.acmphs2} > 0)) ? 0U : 1U) << 26U) | \ ((((${interface.peripheral.acmphs1} > 0)) ? 0U : 1U) << 27U) | \ ((((${interface.peripheral.acmphs0} > 0)) ? 0U : 1U) << 28U)) #endif #ifndef BSP_TZ_CFG_PSARE #define BSP_TZ_CFG_PSARE (\ (1U << 0U) | \ ((((${interface.peripheral.wdt} > 0)) ? 0U : 1U) << 1U) | \ ((((${interface.peripheral.iwdt} > 0)) ? 0U : 1U) << 2U) | \ ((((${interface.peripheral.rtc} > 0)) ? 0U : 1U) << 3U) | \ ((((${interface.peripheral.ulpt1} > 0)) ? 0U : 1U) << 8U) | \ ((((${interface.peripheral.ulpt0} > 0)) ? 0U : 1U) << 9U) | \ ((((${interface.peripheral.gpt0} > 0) || (${interface.peripheral.gpt1} > 0) || (${interface.peripheral.gpt2} > 0) || (${interface.peripheral.gpt3} > 0) || (${interface.peripheral.gpt4} > 0) || (${interface.peripheral.gpt5} > 0) || (${interface.peripheral.gpt6} > 0) || (${interface.peripheral.gpt7} > 0) || (${interface.peripheral.gpt8} > 0) || (${interface.peripheral.gpt9} > 0) || (${interface.peripheral.gpt10} > 0) || (${interface.peripheral.gpt11} > 0) || (${interface.peripheral.gpt12} > 0) || (${interface.peripheral.gpt13} > 0)) ? 0U : 1U) << 15U) | \ ((((${interface.peripheral.gpt13} > 0)) ? 0U : 1U) << 18U) | \ ((((${interface.peripheral.gpt12} > 0)) ? 0U : 1U) << 19U) | \ ((((${interface.peripheral.gpt11} > 0)) ? 0U : 1U) << 20U) | \ ((((${interface.peripheral.gpt10} > 0)) ? 0U : 1U) << 21U) | \ ((((${interface.peripheral.gpt4} > 0)) ? 0U : 1U) << 27U) | \ ((((${interface.peripheral.gpt3} > 0)) ? 0U : 1U) << 28U) | \ ((((${interface.peripheral.gpt2} > 0)) ? 0U : 1U) << 29U) | \ ((((${interface.peripheral.gpt1} > 0)) ? 0U : 1U) << 30U) | \ ((((${interface.peripheral.gpt0} > 0)) ? 0U : 1U) << 31U)) #endif #ifndef BSP_TZ_CFG_MSSAR #define BSP_TZ_CFG_MSSAR (\ (1U << 0U) | \ (1U << 1U) | \ (1U << 2U) | \ (1U << 3U) | \ ((((${interface.peripheral.npu} > 0)) ? 0U : 1U) << 16U) | \ ((((${interface.peripheral.dtc_dmac} > 0)) ? 0U : 1U) << 22U) | \ (1U << 23U) | \ ((((${interface.peripheral.elc} > 0)) ? 0U : 1U) << 31U)) #endif
/* Type 2 Peripheral Security Attribution */
/* Security attribution for RSTSRn registers. */ #ifndef BSP_TZ_CFG_RSTSAR #define BSP_TZ_CFG_RSTSAR (${config.bsp.fsp.tz.rstsar}) #endif
/* Security attribution for registers of LVD channels. */ #ifndef BSP_TZ_CFG_LVDSAR /* The LVD driver needs to access both channels. This means that the security attribution for both channels must be the same. */ #if (${interface.peripheral.lvdmodule.driver.lvd.monitor_number.MONITOR_1} > 0) || (${interface.peripheral.lvdmodule.driver.lvd.monitor_number.MONITOR_2} > 0) #define BSP_TZ_CFG_LVDSAR (0U) #else #define BSP_TZ_CFG_LVDSAR (3U) #endif #endif #ifndef BSP_TZ_CFG_PVDSAR #define BSP_TZ_CFG_PVDSAR (${config.bsp.fsp.tz.pvdsar}) #endif
/* CPU0 owns CPU1 TCM control and boundary attribution; HM 2.17.3.1-2. */ #ifndef BSP_TZ_CFG_TCMSAR #define BSP_TZ_CFG_TCMSAR (${config.bsp.fsp.tz.tcmsar}) #endif #ifndef BSP_TZ_CFG_TCMSABARC #define BSP_TZ_CFG_TCMSABARC (${config.bsp.fsp.tz.tcmsabarc}) #endif #ifndef BSP_TZ_CFG_TCMSABARS #define BSP_TZ_CFG_TCMSABARS (${config.bsp.fsp.tz.tcmsabars}) #endif #if (BSP_TZ_CFG_TCMSAR != 0U) && ((BSP_TZ_CFG_TCMSABARC | BSP_TZ_CFG_TCMSABARS) != 0U) #error "TCM control must be Secure while either CPU1 TCM contains Secure memory" #endif
/* Security attribution for LPM registers. * - OPCCR based on clock security. * - Set remaining registers based on LPM security. */ #ifndef BSP_TZ_CFG_LPMSAR #define BSP_TZ_CFG_LPMSAR (\ ((BSP_CFG_CLOCKS_SECURE == 0) ? 0x00200011U : 0U) | \ ((${interface.peripheral.lpm} > 0) ? 0U : 0x000E0106U)) #endif /* Deep Standby Interrupt Factor Security Attribution Register. */ #ifndef BSP_TZ_CFG_DPFSAR #define BSP_TZ_CFG_DPFSAR ((${interface.peripheral.lpm} > 0) ? 0U : 0xEF1FFFFFU) #endif #ifndef BSP_TZ_CFG_DPFSAR1 #define BSP_TZ_CFG_DPFSAR1 ((${interface.peripheral.lpm} > 0) ? 0U : 0x0000FFFFU) #endif /* RAM Standby Control Security Attribution Register. */ #ifndef BSP_TZ_CFG_RSCSAR #define BSP_TZ_CFG_RSCSAR ((${interface.peripheral.lpm} > 0) ? 0U : 0x00031FFFU) #endif /* Power Gating Control Security Attribution Register */ #ifndef BSP_TZ_CFG_PGCSAR #define BSP_TZ_CFG_PGCSAR ((${config.bsp.fsp.tz.pgcsar} << 1U)) #endif
/* Security attribution for CGC registers. */ #ifndef BSP_TZ_CFG_CGFSAR #if BSP_CFG_CLOCKS_SECURE /* Protect all CGC registers from Non-secure write access. */ #define BSP_TZ_CFG_CGFSAR (0U) #else /* Allow Secure and Non-secure write access. */ #define BSP_TZ_CFG_CGFSAR (0x1F7F7FFDU) #endif #endif
/* Security attribution for Battery Backup registers. */ #ifndef BSP_TZ_CFG_BBFSAR #if ${config.bsp.fsp.tz.bbfsar} #define BSP_TZ_CFG_BBFSAR (0U) #else #define BSP_TZ_CFG_BBFSAR (0x7FU) #endif #endif
/* Security attribution for Battery Backup registers (VBTBKRn). */ #ifndef BSP_TZ_CFG_VBRSABAR #if ${config.bsp.fsp.tz.bbfsar} #define BSP_TZ_CFG_VBRSABAR (0xFFE0) #else #define BSP_TZ_CFG_VBRSABAR (0xED00) #endif #endif
/* Security attribution for registers for IRQ channels. */ #ifndef BSP_TZ_CFG_ICUSARA #define BSP_TZ_CFG_ICUSARA (\ (((${interface.peripheral.irq0} > 0) ? 0U : 1U) << 0U) | \ (((${interface.peripheral.irq1} > 0) ? 0U : 1U) << 1U) | \ (((${interface.peripheral.irq2} > 0) ? 0U : 1U) << 2U) | \ (((${interface.peripheral.irq3} > 0) ? 0U : 1U) << 3U) | \ (((${interface.peripheral.irq4} > 0) ? 0U : 1U) << 4U) | \ (((${interface.peripheral.irq5} > 0) ? 0U : 1U) << 5U) | \ (((${interface.peripheral.irq6} > 0) ? 0U : 1U) << 6U) | \ (((${interface.peripheral.irq7} > 0) ? 0U : 1U) << 7U) | \ (((${interface.peripheral.irq8} > 0) ? 0U : 1U) << 8U) | \ (((${interface.peripheral.irq9} > 0) ? 0U : 1U) << 9U) | \ (((${interface.peripheral.irq10} > 0) ? 0U : 1U) << 10U) | \ (((${interface.peripheral.irq11} > 0) ? 0U : 1U) << 11U) | \ (((${interface.peripheral.irq12} > 0) ? 0U : 1U) << 12U) | \ (((${interface.peripheral.irq13} > 0) ? 0U : 1U) << 13U) | \ (((${interface.peripheral.irq14} > 0) ? 0U : 1U) << 14U) | \ (((${interface.peripheral.irq15} > 0) ? 0U : 1U) << 15U) | \ (((${interface.peripheral.irq16} > 0) ? 0U : 1U) << 16U) | \ (((${interface.peripheral.irq17} > 0) ? 0U : 1U) << 17U) | \ (((${interface.peripheral.irq18} > 0) ? 0U : 1U) << 18U) | \ (((${interface.peripheral.irq19} > 0) ? 0U : 1U) << 19U) | \ (((${interface.peripheral.irq20} > 0) ? 0U : 1U) << 20U) | \ (((${interface.peripheral.irq21} > 0) ? 0U : 1U) << 21U) | \ (((${interface.peripheral.irq22} > 0) ? 0U : 1U) << 22U) | \ (((${interface.peripheral.irq23} > 0) ? 0U : 1U) << 23U) | \ (((${interface.peripheral.irq24} > 0) ? 0U : 1U) << 24U) | \ (((${interface.peripheral.irq25} > 0) ? 0U : 1U) << 25U) | \ (((${interface.peripheral.irq26} > 0) ? 0U : 1U) << 26U) | \ (((${interface.peripheral.irq27} > 0) ? 0U : 1U) << 27U) | \ (((${interface.peripheral.irq28} > 0) ? 0U : 1U) << 28U) | \ (((${interface.peripheral.irq29} > 0) ? 0U : 1U) << 29U) | \ (((${interface.peripheral.irq30} > 0) ? 0U : 1U) << 30U) | \ (((${interface.peripheral.irq31} > 0) ? 0U : 1U) << 31U)) #endif
/* Security attribution for NMI registers. */ #ifndef BSP_TZ_CFG_ICUSARB #define BSP_TZ_CFG_ICUSARB ((${config.bsp.fsp.tz.icusarb.common}) | \ (${config.bsp.fsp.tz.cmsis.bfhfnmins} << 1U) | \ (${config.bsp.fsp.tz.icusarb.cpu1} << 2U)) #endif
/* CPU0 establishes both DMAC channel banks and matching MMPU attribution. */ #ifndef BSP_TZ_CFG_DMACCHSAR_LOCAL #define BSP_TZ_CFG_DMACCHSAR_LOCAL (\ (((${interface.peripheral.dmac0} > 0) ? 0U : 1U) << 0U) /* DMAC Channel 0 */ | \ (((${interface.peripheral.dmac1} > 0) ? 0U : 1U) << 1U) /* DMAC Channel 1 */ | \ (((${interface.peripheral.dmac2} > 0) ? 0U : 1U) << 2U) /* DMAC Channel 2 */ | \ (((${interface.peripheral.dmac3} > 0) ? 0U : 1U) << 3U) /* DMAC Channel 3 */ | \ (((${interface.peripheral.dmac4} > 0) ? 0U : 1U) << 4U) /* DMAC Channel 4 */ | \ (((${interface.peripheral.dmac5} > 0) ? 0U : 1U) << 5U) /* DMAC Channel 5 */ | \ (((${interface.peripheral.dmac6} > 0) ? 0U : 1U) << 6U) /* DMAC Channel 6 */ | \ (((${interface.peripheral.dmac7} > 0) ? 0U : 1U) << 7U) /* DMAC Channel 7 */) #endif #ifndef BSP_TZ_CFG_DMACCHSAR_CPU1 #define BSP_TZ_CFG_DMACCHSAR_CPU1 (${config.bsp.fsp.tz.dmacchsar.cpu1}) #endif #if (BSP_TZ_CFG_DMACCHSAR_CPU1 & ~0xFFU) != 0U #error "CPU1 Non-secure DMA channel mask must be an integer from 0 to 0xFF" #endif #ifndef BSP_TZ_CFG_DMACCHSAR #define BSP_TZ_CFG_DMACCHSAR (BSP_TZ_CFG_DMACCHSAR_LOCAL | (BSP_TZ_CFG_DMACCHSAR_CPU1 << 16U)) #endif
/* Security attribution registers for WUPEN0. */ #ifndef BSP_TZ_CFG_ICUSARE #define BSP_TZ_CFG_ICUSARE ((${interface.peripheral.lpm} > 0) ? 0U : 0xFF1D0000U) #endif
/* Security attribution registers for WUPEN1. */ #ifndef BSP_TZ_CFG_ICUSARF #define BSP_TZ_CFG_ICUSARF ((${interface.peripheral.lpm} > 0) ? 0U : 0x0000FF88U) #endif
/* Trusted Event Route Control Register for IELSR, DMAC.DELSR and ELC.ELSR. Note that currently Trusted Event Route Control is not supported. */ #ifndef BSP_TZ_CFG_TEVTRCR #define BSP_TZ_CFG_TEVTRCR (0) #endif
/* Security attribution register for ELCR, ELSEGR0, ELSEGR1 Security Attribution. */ #ifndef BSP_TZ_CFG_ELCSARA #define BSP_TZ_CFG_ELCSARA (0x0000001FU) #endif
/* Set DTCSTSAR if the Secure program uses the DTC. */ #if ${interface.peripheral.dtc} == RA_NOT_DEFINED #define BSP_TZ_CFG_DTC_USED (0U) #else #define BSP_TZ_CFG_DTC_USED (1U) #endif
/* CPU0 establishes both controller banks; reserved bits remain zero (HM 17.2.3, 18.2.1). */ #ifndef BSP_TZ_CFG_DMACSAR #define BSP_TZ_CFG_DMACSAR ((${config.bsp.fsp.tz.dmacsar.cpu0}) | \ ((${config.bsp.fsp.tz.dmacsar.cpu1}) << 16U)) #endif #ifndef BSP_TZ_CFG_DTCSAR #define BSP_TZ_CFG_DTCSAR ((${config.bsp.fsp.tz.dtcsar.cpu0}) | \ ((${config.bsp.fsp.tz.dtcsar.cpu1}) << 16U)) #endif
/* MRAM security attribution; HM 60.5.13. */ #ifndef BSP_TZ_CFG_MSAR #define BSP_TZ_CFG_MSAR (\ ((BSP_CFG_CLOCKS_SECURE == 0) ? 0x000AU : 0U) | \ ((${interface.peripheral.mram} > 0) ? 0U : 0xEE15U)) #endif #ifndef BSP_TZ_CFG_FSAR #define BSP_TZ_CFG_FSAR (0U) #endif
/* Security attribution for SRAM registers. */ #ifndef BSP_TZ_CFG_SRAMSAR /* If the CGC registers are only accessible in Secure mode, than there is no reason for Non Secure applications to access * SRAM0WTEN and therefore there is no reason to access PRCR2. */ #define BSP_TZ_CFG_SRAMSAR (\ ((${config.bsp.fsp.tz.sramsar.sramsa0}) << 0U) | /* SRAMSA0 */\ ((${config.bsp.fsp.tz.sramsar.sramsa1}) << 1U) | /* SRAMSA1 */\ ((${config.bsp.fsp.tz.sramsar.sramsa2}) << 2U) | /* SRAMSA2 */\ ((${config.bsp.fsp.tz.sramsar.sramsa3}) << 3U) | /* SRAMSA3 */\ ((BSP_CFG_CLOCKS_SECURE == 0) ? (1U << 8U) : 0U) /* SRAMWTSA */) #endif
/* Security attribution for the DMAC Bus Master MPU settings. */ #ifndef BSP_TZ_CFG_MMPUSARA /* The DMAC Bus Master MPU settings should align with the DMAC channel settings. */ #define BSP_TZ_CFG_MMPUSARA (BSP_TZ_CFG_DMACCHSAR) #endif
/* Security Attribution Register A for BUS Control registers. */ #ifndef BSP_TZ_CFG_BUSSARA #define BSP_TZ_CFG_BUSSARA (${config.bsp.fsp.tz.bussara}) #endif /* Security Attribution Register B for BUS Control registers. */ #ifndef BSP_TZ_CFG_BUSSARB #define BSP_TZ_CFG_BUSSARB (${config.bsp.fsp.tz.bussarb}) #endif /* Security Attribution Register C for BUS Control registers. */ #ifndef BSP_TZ_CFG_BUSSARC #define BSP_TZ_CFG_BUSSARC (${config.bsp.fsp.tz.bussarc}) #endif
/* Enable Uninitialized Non-Secure Application Fallback. */ #ifndef BSP_TZ_CFG_NON_SECURE_APPLICATION_FALLBACK #define BSP_TZ_CFG_NON_SECURE_APPLICATION_FALLBACK (${config.bsp.fsp.tz.uninitialized_ns_application_fallback}) #endif
#define OFS_SEQ1 0xA001A001 | (${config.bsp.fsp.OFS0.iwdt_start_mode}) | (${config.bsp.fsp.OFS0.iwdt_timeout}) #define OFS_SEQ2 (${config.bsp.fsp.OFS0.iwdt_divisor}) | (${config.bsp.fsp.OFS0.iwdt_window_end}) | (${config.bsp.fsp.OFS0.iwdt_window_start}) #define OFS_SEQ3 (${config.bsp.fsp.OFS0.iwdt_reset_interrupt}) | (${config.bsp.fsp.OFS0.iwdt_stop_control}) | (${config.bsp.fsp.OFS0.wdt_start_mode}) #define OFS_SEQ4 (${config.bsp.fsp.OFS0.wdt_timeout}) |(${config.bsp.fsp.OFS0.wdt_divisor}) | (${config.bsp.fsp.OFS0.wdt_window_end}) | (${config.bsp.fsp.OFS0.wdt_window_start}) #define OFS_SEQ5 (${config.bsp.fsp.OFS0.wdt_reset_interrupt}) | (${config.bsp.fsp.OFS0.wdt_stop_control}) #define BSP_CFG_ROM_REG_OFS0 (OFS_SEQ1 | OFS_SEQ2 | OFS_SEQ3 | OFS_SEQ4 | OFS_SEQ5)
#define BSP_CFG_ROM_REG_OFS2 (0xFFFFFFC0U | (${config.bsp.fsp.OFS2.dcdc}) | (${config.bsp.fsp.OFS2.cvm_reset}) | (${config.bsp.fsp.OFS2.npu_security}) | (${config.bsp.fsp.OFS2.npu_privilege}) | (${config.bsp.fsp.OFS2.external_vdd}))
/* WDT1 options: reserved OFS3 bits must be programmed as zero (HM 7.2.6). */ #ifndef BSP_CFG_ROM_REG_OFS3 #define BSP_CFG_ROM_REG_OFS3 (\ (${config.bsp.fsp.OFS3.wdt_start_mode}) | \ (${config.bsp.fsp.OFS3.wdt_timeout}) | \ (${config.bsp.fsp.OFS3.wdt_divisor}) | \ (${config.bsp.fsp.OFS3.wdt_window_end}) | \ (${config.bsp.fsp.OFS3.wdt_window_start}) | \ (${config.bsp.fsp.OFS3.wdt_reset_interrupt}) | \ (${config.bsp.fsp.OFS3.wdt_stop_control})) #endif #ifndef BSP_CFG_ROM_REG_OFS3_SEL #define BSP_CFG_ROM_REG_OFS3_SEL (\ (${config.bsp.fsp.OFS3_SEL.wdt_start_mode}) | \ (${config.bsp.fsp.OFS3_SEL.wdt_timeout}) | \ (${config.bsp.fsp.OFS3_SEL.wdt_divisor}) | \ (${config.bsp.fsp.OFS3_SEL.wdt_window_end}) | \ (${config.bsp.fsp.OFS3_SEL.wdt_window_start}) | \ (${config.bsp.fsp.OFS3_SEL.wdt_reset_interrupt}) | \ (${config.bsp.fsp.OFS3_SEL.wdt_stop_control})) #endif
/* Option Function Select Register 1 Security Attribution */ #ifndef BSP_CFG_ROM_REG_OFS1_SEL #if defined(_RA_TZ_SECURE) || defined(_RA_TZ_NONSECURE) #define BSP_CFG_ROM_REG_OFS1_SEL (0x00000000U | (${config.bsp.fsp.OFS1_SEL.voltage_detection0_level}) | (${config.bsp.fsp.OFS1_SEL.voltage_detection0.start}) | (${config.bsp.fsp.OFS1_SEL.voltage_detection0.low_power_consumption}) | ((BSP_CFG_CLOCKS_SECURE == 0) ? 0xF00U : 0U) | (${config.bsp.fsp.OFS1_SEL.swdbg}) | (${config.bsp.fsp.OFS1_SEL.initeccen})) #else #define BSP_CFG_ROM_REG_OFS1_SEL (0x00000000U) #endif #endif #define BSP_CFG_ROM_REG_OFS1_INITECCEN (${config.bsp.fsp.OFS1.initeccen}) /* HOCOFRQ0 uses the clock-tree encoding; reserved bits remain one (HM 7.2.4). */ #define BSP_CFG_ROM_REG_OFS1 (0xFCFFF0D0U | (${config.bsp.fsp.OFS1.voltage_detection0.start}) | (${config.bsp.fsp.OFS1.voltage_detection0_level}) | (${config.bsp.fsp.OFS1.voltage_detection0.low_power_consumption}) | (${config.bsp.fsp.OFS1.hoco_osc}) | (BSP_CFG_HOCO_FREQUENCY << 9U) | (${config.bsp.fsp.OFS1.swdbg}) | (BSP_CFG_ROM_REG_OFS1_INITECCEN))
