/* MRAM protection: HM 7.2.8-9, 60.8.3 and 60.9.1.2. */ #define BSP_CFG_ROM_REG_BPS_WORD_COUNT (16U) #define BSP_CFG_ROM_REG_PBPS_WORD_COUNT (4U) #ifndef BSP_CFG_ROM_REG_BPS0 #define BSP_CFG_ROM_REG_BPS0 (~(${config.bsp.fsp.BPS.BPS0} 0U)) #endif #ifndef BSP_CFG_ROM_REG_BPS1 #define BSP_CFG_ROM_REG_BPS1 (~(${config.bsp.fsp.BPS.BPS1} 0U)) #endif #ifndef BSP_CFG_ROM_REG_BPS2 #define BSP_CFG_ROM_REG_BPS2 (~(${config.bsp.fsp.BPS.BPS2} 0U)) #endif #ifndef BSP_CFG_ROM_REG_BPS3 #define BSP_CFG_ROM_REG_BPS3 (~(${config.bsp.fsp.BPS.BPS3} 0U)) #endif #ifndef BSP_CFG_ROM_REG_BPS4 #define BSP_CFG_ROM_REG_BPS4 (~(${config.bsp.fsp.BPS.BPS4} 0U)) #endif #ifndef BSP_CFG_ROM_REG_BPS5 #define BSP_CFG_ROM_REG_BPS5 (~(${config.bsp.fsp.BPS.BPS5} 0U)) #endif #ifndef BSP_CFG_ROM_REG_BPS6 #define BSP_CFG_ROM_REG_BPS6 (~(${config.bsp.fsp.BPS.BPS6} 0U)) #endif #ifndef BSP_CFG_ROM_REG_BPS7 #define BSP_CFG_ROM_REG_BPS7 (~(${config.bsp.fsp.BPS.BPS7} 0U)) #endif #ifndef BSP_CFG_ROM_REG_BPS8 #define BSP_CFG_ROM_REG_BPS8 (~(${config.bsp.fsp.BPS.BPS8} 0U)) #endif #ifndef BSP_CFG_ROM_REG_BPS9 #define BSP_CFG_ROM_REG_BPS9 (~(${config.bsp.fsp.BPS.BPS9} 0U)) #endif #ifndef BSP_CFG_ROM_REG_BPS10 #define BSP_CFG_ROM_REG_BPS10 (~(${config.bsp.fsp.BPS.BPS10} 0U)) #endif #ifndef BSP_CFG_ROM_REG_BPS11 #define BSP_CFG_ROM_REG_BPS11 (~(${config.bsp.fsp.BPS.BPS11} 0U)) #endif #ifndef BSP_CFG_ROM_REG_BPS12 #define BSP_CFG_ROM_REG_BPS12 (~(${config.bsp.fsp.BPS.BPS12} 0U)) #endif #ifndef BSP_CFG_ROM_REG_BPS13 #define BSP_CFG_ROM_REG_BPS13 (~(${config.bsp.fsp.BPS.BPS13} 0U)) #endif #ifndef BSP_CFG_ROM_REG_BPS14 #define BSP_CFG_ROM_REG_BPS14 (~(${config.bsp.fsp.BPS.BPS14} 0U)) #endif #ifndef BSP_CFG_ROM_REG_BPS15 #define BSP_CFG_ROM_REG_BPS15 (~(${config.bsp.fsp.BPS.BPS15} 0U)) #endif #ifndef BSP_CFG_ROM_REG_PBPS0 #define BSP_CFG_ROM_REG_PBPS0 (~(${config.bsp.fsp.PBPS.PBPS0} 0U)) #endif #ifndef BSP_CFG_ROM_REG_PBPS1 #define BSP_CFG_ROM_REG_PBPS1 (~(${config.bsp.fsp.PBPS.PBPS1} 0U)) #endif #ifndef BSP_CFG_ROM_REG_PBPS2 #define BSP_CFG_ROM_REG_PBPS2 (~(${config.bsp.fsp.PBPS.PBPS2} 0U)) #endif #ifndef BSP_CFG_ROM_REG_PBPS3 #define BSP_CFG_ROM_REG_PBPS3 (~(${config.bsp.fsp.PBPS.PBPS3} 0U)) #endif #ifndef BSP_CLOCK_CFG_MAIN_OSC_WAIT #define BSP_CLOCK_CFG_MAIN_OSC_WAIT (${config.bsp.common.main_osc_wait}) #endif
